use uor_r4_core::native_geometric::{Control, Model, WordCopyProgress, BOS};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let path = std::env::args().nth(1).ok_or("model path required")?;
    let model = Model::from_bytes(&std::fs::read(path)?)?;
    println!("artifact={}", model.artifact_cid());
    let mut signatures = Vec::new();
    for (id, prompt, target) in [
        ("two-operations", "Start with five. Add two, then double the result. Answer:", "14"),
        ("relation", "The red box belongs to Alice. Alice lives in Rome. Where does the owner of the red box live? Answer:", "Rome"),
        ("copy", "the orb is red. the cube is green. Now the orb is blue. Question: What color is the orb? Answer:", "blue"),
    ] {
        let tokens = model.encode(prompt)?;
        let tail = tokens.iter().rev().take(8).copied().collect::<Vec<_>>();
        let mut full = model.session(Control::Full)?;
        let mut disabled = model.session(Control::LearnedRoutingDisabled)?;
        for session in [&mut full, &mut disabled] {
            session.observe(&model, BOS)?;
            for &token in &tokens { session.observe(&model, token)?; }
            session.begin_response(&model)?;
        }
        let state = full.state();
        let flags = u32::from(state.response_entry.as_ref().is_some_and(|s| s.boundary_seen.is_some()))
            | (u32::from(state.response_entry.as_ref().is_some_and(|s| s.active)) << 1)
            | (u32::from(state.word_copy.as_ref().is_some_and(|s| matches!(s.progress, WordCopyProgress::Complete))) << 2);
        let base = disabled.predict(&model)?;
        let prediction = full.predict(&model)?;
        let route = full.routing_decision();
        println!("id={id} target={target:?} tail_newest_first={tail:?} parent_token={} flags={flags} prediction={} route={route:?}", base.token, prediction.token);
        signatures.push((tail, route, base.token, flags));
    }
    println!("all_routing_and_joint_output_inputs_equal={}", signatures.windows(2).all(|w| w[0] == w[1]));
    Ok(())
}
